--- workspace/deliverable/comparison.json
+++ workspace/deliverable/comparison.json
@@ -83,8 +83,8 @@
       "adjustments_outside_headline": "add 9,800 to every threshold if Buyer A leaves the Hardaway/warranty tail with Ray (buyer_A_liability_tail: net cost 7,840 / 0.80; 12,250 if no tax offset is credited); add 70,875 to every threshold if Hensley's after-tax note interest (90,000 - 33,300 = 56,700) is credited without discounting (no time-value rule in library - unverified), giving 3,385,550 / 3,332,425 / 3,247,425; both adjustments together total 80,675, giving 3,395,350 / 3,342,225 / 3,257,225"
     },
     "buyer_A_liability_tail": {
       "disclosed": "Hardaway dispute $9,800 (disputed); customary warranty obligations, amount unspecified",
-      "effect": "Buyer A assumes only listed trade payables, so these ride with the entity Ray liquidates and come out of company cash first (estimated net 2,192,260 - 9,800 = 2,182,460 if Hardaway is ultimately paid; warranty unquantified). Tax effect immaterial (worst-case swing 9,800 x 17% = 1,666) and the character of any offsetting loss is not addressed by the library - left open rather than forced. Buyer B assumes all liabilities known and unknown, so stock_sale_buyer_b figures are unchanged; the Hardaway item is a known liability, so disclosure in the reps is required."
+      "effect": "Buyer A assumes only listed trade payables, so these ride with the entity Ray liquidates and come out of company cash first. On the memo section 4 rollforward: a 9,800 payment out of company cash shrinks the liquidating distribution and the 160,000 liquidating capital gain one-for-one (ordinary income unchanged), recovering 9,800 x 20% = 1,960 of tax, a net cost of 7,840 - estimated net 2,192,260 - 7,840 = 2,184,420 if Hardaway is ultimately paid (conservative floor 2,182,460 if no tax offset is credited); warranty unquantified. Whether the payment itself is deductible as an ordinary loss is not addressed by the library - left open rather than forced (a few thousand dollars at most). Buyer B assumes all liabilities known and unknown, so stock_sale_buyer_b figures are unchanged; the Hardaway item is a known liability, so disclosure in the reps is required."
     }
   }
 }
